fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0';
if ~exist('fit_resEi200','var')
    %fit_data_file = 'FitEn_cut200_1Dsbg_dirGH_dE20_fix_bg_slope.mat'; % fit 1D background with no Q-slope
    fit_data_file = 'FitEn_cut200_1D_fit_bg_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
    ld = load(fullfile(fit_data_path,fit_data_file));
    fit_resEi200 = ld.fit_res;
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
if ~exist('cuts2fit200','var')
    ld = load(fullfile(data_path,'multicuts_fit_dataGH_ei200meV.mat'));
    cuts2fit200 = ld.cuts2fit200;
end
cuts2fit = cuts2fit200;
fit_res = fit_resEi200;
mi = maps_instrument(200,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for i=1:numel(cuts2fit.cutsS_list)
    cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end

%%
acolor g
Sgnl = fit_res.S;  
pd(Sgnl);ly 0 2;liny;keep_figure %[output:819e80b8]
J0 = fit_res.J0;
pd(J0);ly 20 60;keep_figure %[output:2c7ea2cd]
G = fit_res.gamma;
G.s_axis.units = 'meV';
pd(G);ly 0 100;keep_figure %[output:87febe60]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:1a6e3b82]
e_min = Sgnl.x(1);

%%
En = 50 %[output:0097d801]
dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_idx =  floor((En-e_min)/dE)+1;
the2Dcuts = cuts2fit.cutsS_list;%(1:2);
init_fg_params = fit_res.all_fit_par(en_idx).p;
init_bg_params = fit_res.all_fit_par(en_idx).bp;
%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,true) %[output:9d01d1b9] %[output:1b4bcac5] %[output:216e5dba] %[output:7d910a66] %[output:9e295d5c] %[output:32038a15] %[output:87be5824] %[output:8d13c228]
%%
%fit_res.all_fit_par(en_idx) = fit_par;
acolor r
plot(fit_res.S);ly 0 4;liny;
acolor g
Sgnl.signal(en_idx) = fit_par.p(4);
pd(Sgnl);ly 0 4;liny;keep_figure

acolor r
plot(fit_res.J0);ly 0 100;liny;
acolor g
J0.signal(en_idx) = fit_par.p(6);
pd(J0);ly 0 100;keep_figure

acolor r
plot(fit_res.gamma);ly 0 300;liny;
acolor g
G.signal(en_idx) = fit_par.p(3);
pd(G);ly 0 300;keep_figure


